import {demoStore} from './demo-data.js';
import {legalPages} from './legal.js';
const app=document.querySelector('#app'), modal=document.querySelector('#modal');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID().replaceAll('-','');
let session={user:null,tenants:[],csrf:''},catalog={gateways:[]},state=null,tab='overview',demo=false,store=null,search='',category='All',sort='featured';
const local={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{toast('Your browser could not save these changes.');}},remove(k){localStorage.removeItem(k);}};
const demoKey='icss-plaza-demo-v1';
const money=(cents,currency=state?.settings?.currency||store?.settings?.currency||'JMD')=>new Intl.NumberFormat('en-JM',{style:'currency',currency,maximumFractionDigits:2}).format(cents/100);
const logo=()=>'<a class="logo" href="/"><img src="/assets/plaza.svg" alt=""><span>ICSS <em>Plaza</em></span></a>';
const button=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const field=(label,name,value='',type='text',hint='')=>`<label class="field">${esc(label)}<input type="${type}" name="${name}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''}>${hint?`<span class="helper">${hint}</span>`:''}</label>`;
const area=(label,name,value='')=>`<label class="field">${esc(label)}<textarea name="${name}">${esc(value)}</textarea></label>`;
const check=(label,name,value)=>`<label class="field check"><input name="${name}" type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;
const select=(label,name,value,items)=>`<label class="field">${esc(label)}<select name="${name}">${items.map(([k,v])=>`<option value="${esc(k)}" ${value===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',5000);}
async function api(path,method='GET',data){const r=await fetch(path,{method,headers:{'Content-Type':'application/json',...(session.csrf?{'X-CSRF-Token':session.csrf}:{})},...(data?{body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed.');return result;}
function showModal(html){modal.innerHTML=`<div class="dialog-head"><span></span><button class="close" data-action="close" aria-label="Close dialog">×</button></div>`+html;modal.showModal();}
function errorPage(error){app.innerHTML=`<div class="error-page">${logo()}<h1 style="margin-top:40px">${esc(error.message)}</h1><a class="btn" href="/">Back to ICSS Plaza</a></div>`;}
function footer(){return `<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div>${logo()}<p>More businesses online. More possibilities.<br>Owned and operated by iCreate Solutions & Services, Jamaica.</p><p><a href="mailto:icreatesolutions.ja@gmail.com">icreatesolutions.ja@gmail.com</a><br><a href="https://wa.me/18765857469">WhatsApp +1 876-585-7469</a></p></div><div class="footer-links"><a href="/legal/terms">Terms</a><a href="/legal/privacy">Privacy</a><a href="/legal/refunds">Cancellation & refunds</a><a href="/legal/acceptable-use">Acceptable use</a><a href="/legal/cookies">Cookies</a></div></div><div class="copyright">© ${new Date().getFullYear()} iCreate Solutions & Services. ICSS Plaza. Independent stores. One place to start.</div></div></footer>`;}
function nav(){return `<header class="wrap"><nav class="site-nav" aria-label="Main navigation">${logo()}<div class="nav-links"><a href="/#how">How it works</a><a href="/#demo">Live demo</a><a href="/#payments">Payments</a><a href="/#rental">Store rental</a></div><div class="nav-actions"><a href="/login">Log in</a><a class="btn" href="/signup">Start your store <span class="arrow">↗</span></a></div></nav></header>`;}
function mini(s=demoStore().settings){return `<div class="window"><div class="window-chrome"><i></i><i></i><i></i><span>ICSS Plaza / ${esc(s.name.toLowerCase().replaceAll(' ','-'))}</span></div><div class="mini-nav">${esc(s.name)}<small><span>Shop</span><span>Our story</span><span>Bag (0)</span></small></div><div class="mini-hero"><div class="mini-copy"><small>${esc(s.tagline)}</small><h3>${esc(s.heroTitle)}</h3><span class="pill" style="background:${esc(s.accent)}">${esc(s.heroButton)}</span></div><img src="/assets/collection.svg" alt="Sample store collection"></div><div class="mini-products">${['serum','tote','candle'].map((x,i)=>`<div><img src="/assets/${x}.svg" alt="Sample product"><p>${['Botanical body oil','The everyday tote','Calm candle'][i]}</p></div>`).join('')}</div></div>`;}
function landing(){app.innerHTML=nav()+`<main><div class="wrap"><section class="hero"><div><div class="eyebrow"><span class="dot"></span>Built for the next step in your business</div><h1>Your business.<br>Your store.<br><span>Within reach.</span></h1><p class="lead">You don’t need a big website budget to start selling online. Rent a beautiful store, make it yours, and run it all from one simple dashboard.</p><div class="row"><a class="btn" href="/signup">Start your store <span class="arrow">↗</span></a><a class="btn outline" href="#demo">Try the live demo <span>▷</span></a></div><div class="micro"><span>✓ No coding needed</span><span>✓ Your brand, your products</span><span>✓ 14-day trial</span></div></div><div class="hero-art">${mini()}<div class="float-card top"><span class="success-icon">✓</span><div><strong>Your store. Your style.</strong><p>Make every detail your own.</p></div></div><div class="float-card bottom"><span class="success-icon">↗</span><div><strong>Ready for your next chapter</strong><p>From your dashboard to your customers.</p></div></div></div></section><div class="band"><span>ONE STOREFRONT. ENDLESS POSSIBILITIES.</span><strong>Beauty & wellness</strong><strong>Fashion & accessories</strong><strong>Home & lifestyle</strong><strong>Products & services</strong></div><section class="section" id="how"><div class="section-head"><div><div class="eyebrow">A smaller step. A bigger opportunity.</div><h2>From idea to open for business.</h2></div><p>A store that looks like you, with the tools to keep your business moving.</p></div><div class="feature-grid"><article class="feature"><span class="num">01</span><h3>Claim your corner.</h3><p>Choose your store name and address. Start with a ready-made storefront inspired by the ForYou Skin Bar shopping experience.</p></article><article class="feature"><span class="num">02</span><h3>Make it unmistakably you.</h3><p>Change the colours, logo, banners, photos, products, prices and page content. Your dashboard puts you in control.</p></article><article class="feature"><span class="num">03</span><h3>Give customers a way to pay.</h3><p>Connect your merchant account, choose a default payment method, and manage orders and inventory in one place.</p></article></div></section><section class="demo-section" id="demo"><div class="section-head"><div><div class="eyebrow">Take the controls</div><h2>Don’t just picture it.<br>Play with it.</h2></div><p>Change a few details and watch your sample store come to life. Then explore the full dashboard.</p></div><div class="demo-shell"><form id="mini-editor" class="demo-editor"><h3>A little preview of your control.</h3><p>These changes affect this sample only.</p>${field('Store name','name','Island Studio')}${field('Hero headline','heroTitle','Everyday essentials. A little extraordinary.')}${field('Brand colour','accent','#9c7035','color')}<a class="btn" href="/demo">Open the full demo ↗</a></form><div class="demo-preview" id="mini-preview">${mini()}</div></div><div class="demo-foot"><p>Fictional products. No real payments. No account needed.</p><a class="btn lime sm" href="/demo">Try products, images & payments →</a></div></section><section class="section" id="payments"><div class="section-head"><div><div class="eyebrow">Your sales. Your payment provider.</div><h2>Built for how Jamaica pays.</h2></div><p>Choose what works for your business and set your default method in the dashboard.</p></div><div class="gateway-row"><div class="gateway-word">Fygaro</div><div class="gateway-word">PayPal</div><div class="gateway-word">WiPay</div><div class="gateway-word">EzeePayments</div><div class="gateway-word">Lynk</div></div><p class="payment-note">Also configure bank transfers, cash on delivery, NCB / Powertranz, Scotiabank and other merchant-hosted links. Automated checkout adapters are included for Fygaro, PayPal and WiPay; other options use manual reconciliation. Merchant approval, supported currencies, credentials and provider fees apply. Provider names identify available choices and do not imply partnership.</p></section><section class="section" id="rental" style="padding-top:0"><div class="section-head"><div><div class="eyebrow">A storefront without the full build cost</div><h2>Start small. Make room to grow.</h2></div><p>Try the controls first. We’ll agree on your rental package before any paid activation.</p></div><div class="plans"><article class="plan"><span class="tag">EXPLORE FIRST</span><h3 style="margin-top:22px">Your 14-day trial</h3><p>Get familiar with your store. No card required. No automatic trial-end charge.</p><ul><li>Your own store dashboard and address</li><li>Editable branding, pages, products and images</li><li>Inventory, orders and payment configuration</li><li>Store export and cancellation controls</li></ul><a class="btn" href="/signup">Create your trial store →</a></article><article class="plan dark"><span class="tag">YOUR NEXT STEP</span><h3 style="margin-top:22px">A rental that fits your business</h3><p>Talk to iCreate Solutions & Services about your monthly rental, setup and support needs.</p><ul><li>Agree on your price and billing period</li><li>Discuss custom domains and setup help</li><li>Use your own approved merchant account</li><li>Keep ownership of your store content</li></ul><a class="btn outline" href="https://wa.me/18765857469?text=Hi%2C%20I%27m%20interested%20in%20renting%20an%20ICSS%20Plaza%20store.">Let’s talk about your store ↗</a></article></div></section><section class="cta"><h2>That business you’re building?<br>Let’s give it a place online.</h2><a class="btn" href="/signup">Start your store ↗</a></section></div></main>`+footer();}
function legal(){const key=location.pathname.split('/')[2]||'terms',p=legalPages[key];if(!p)return errorPage(Error('Policy not found.'));document.title=p.title+' | ICSS Plaza';app.innerHTML=nav()+`<article class="legal"><div class="eyebrow">iCreate Solutions & Services · Jamaica</div><h1>${p.title}</h1><p>Effective 17 October 2026</p><nav class="legal-nav">${Object.entries(legalPages).map(([k,v])=>`<a class="tag" href="/legal/${k}">${v.title}</a>`).join('')}</nav>${p.sections.map(([h,b])=>`<h2>${esc(h)}</h2><p>${esc(b)}</p>`).join('')}</article>`+footer();}
function authPage(kind){const signup=kind==='signup',reset=kind==='reset';app.innerHTML=`<main class="auth">${logo()}<h1>${signup?'Make room for your business.':reset?'Choose a new password.':'Welcome back.'}</h1><p>${signup?'Create your store and explore a 14-day trial. No payment card needed.':reset?'Enter the one-time token provided by support.':'Sign in to manage your store.'}</p><form data-form="${kind}">${signup?field('Store name','name','')+field('Store address','slug','','text','Your store will live at /s/your-store. Use letters, numbers and hyphens.'):''}${!reset?field('Email address','email','','email'):field('Reset token','token')}${field('Password','password','','password',signup||reset?'Use at least 12 characters.':'')}${signup?`<label class="field check"><input name="acceptTerms" type="checkbox" required><span>I accept the <a href="/legal/terms" target="_blank">platform terms</a> and have read the <a href="/legal/privacy" target="_blank">privacy notice</a>.</span></label>`:''}<div class="form-error"></div><button class="btn" type="submit">${signup?'Create my store →':reset?'Reset password':'Sign in →'}</button></form><a class="small" href="${signup?'/login':'/signup'}">${signup?'Already have an account? Sign in':'New here? Create your store'}</a>${!signup?'<p class="small">Need help signing in? <a href="mailto:icreatesolutions.ja@gmail.com">Contact support</a> for a verified one-time reset token. <a href="/reset">Use reset token</a></p>':''}<a class="small" href="/demo">Explore the dashboard demo first ↗</a></main>`;}
function loadDemo(){let d=local.get(demoKey,null);if(!d||!d.settings||!Array.isArray(d.products))d=demoStore();state=d;}
function saveDemo(){local.set(demoKey,state);}
const tenantId=()=>state.id;
async function refresh(){if(demo){saveDemo();return;}const r=await api('/api/admin/'+tenantId());state={...r.tenant,...r};delete state.tenant;}
function shell(content){const tabs=[['overview','Overview'],['products','Products'],['appearance','Store designer'],['content','Content & policies'],['media','Media library'],['payments','Payment methods'],['orders','Orders'],['settings','Store settings']];app.innerHTML=`${demo?`<div class="banner"><span><strong>Demo playground</strong> · Changes stay in this browser. No real payments or orders.</span><div class="row" style="gap:10px">${button('Reset demo','reset-demo','outline sm')}<a class="btn sm" href="/signup">Get your own store ↗</a></div></div>`:''}<div class="workspace"><aside class="sidebar">${logo()}${tabs.map(([key,label])=>`<button data-tab="${key}" class="${tab===key?'active':''}">${label}</button>`).join('')}<div class="side-bottom"><a href="${demo?'/demo?view=store':'/s/'+state.slug}" target="_blank">View storefront ↗</a>${session.operator?'<a href="/operator">Platform operator ↗</a>':''}${!demo?button('Sign out','logout','outline sm'):''}</div></aside><main class="main-work"><header class="work-head"><div><div class="eyebrow" style="margin-bottom:12px">${esc(state.settings.name)} <span class="tag">${demo?'Sample store':esc(state.status)}</span></div><h1>${esc(tabs.find(x=>x[0]===tab)?.[1]||'Your store')}</h1><p>${demo?'Explore every control. Make this store your own.':`Store address: /s/${esc(state.slug)} · ${state.settings.published?'Published':'Draft'}`}</p></div><div class="row">${button('Preview store ↗','preview','outline sm')}${!demo?button(state.settings.published?'Unpublish':'Publish store',state.settings.published?'unpublish':'publish','sm'):''}</div></header>${content}</main></div>`;}
function imageSelect(name,value){const items=[['','No image'],['/assets/collection.svg','Sample collection'],...['serum','tote','mug','candle'].map(x=>['/assets/'+x+'.svg','Sample '+x]),...state.images.map(i=>[i.url||'/api/images/'+i.id,i.name])];return select('Choose image',name,value,items);}
function overview(){const s=state.settings;const paid=state.orders.filter(o=>o.paid);const checks=[[state.products.some(p=>p.active),'Add your products','products'],[!!s.logo,'Upload your logo','media'],[!!s.address&&!!s.contactEmail,'Add seller details and policies','content'],[!!s.defaultPayment,'Set up a payment method','payments'],[s.published,'Publish your storefront','settings']];return `<div class="stats"><div class="stat"><p>Revenue · confirmed payments</p><strong>${money(state.metrics?.confirmedRevenue??paid.reduce((a,o)=>a+o.total,0))}</strong></div><div class="stat"><p>Orders</p><strong>${state.metrics?.orderCount??state.orders.length}</strong></div><div class="stat"><p>Active products</p><strong>${state.products.filter(p=>p.active).length}</strong></div></div><div class="split"><section class="panel"><h2>Your store, step by step.</h2><p>Bring your brand to life with a few thoughtful details.</p><div class="checklist">${checks.map(([done,label,t])=>`<button data-tab="${t}" class="${done?'done':''}">${done?'✓':'○'} &nbsp;${label} →</button>`).join('')}</div></section><section class="panel"><h2>A home for your next chapter.</h2><p>Control your storefront, keep track of your products, and manage orders from here.</p>${demo?'<div class="note">Try changing your brand colours, adding a product or completing a sample checkout. This is a fictional shop.</div>':`<div class="note">${state.status==='trial'?'Trial ends '+new Date(state.trial_end).toLocaleDateString()+' — no automatic charge. Agree on a rental with ICSS before paid activation.':'Rental status: '+esc(state.status)+'. Contact support about billing or package changes.'}</div>`}<a class="btn outline sm" href="https://wa.me/18765857469">Talk to iCreate ↗</a></section></div>`;}
function productsPanel(){return `<section class="panel"><div class="section-head" style="margin-bottom:15px"><div><h2>Your collection</h2><p class="small">Prices use ${esc(state.settings.currency)}. Add variants for size, colour or other choices.</p></div>${button('+ Add product','add-product','sm')}</div><div class="table-scroll"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody>${state.products.map(p=>`<tr><td><div class="table-product"><img class="thumb" src="${esc(p.image||'/assets/collection.svg')}" alt=""><div><strong>${esc(p.name)}</strong><p class="small">${esc(p.sku)}</p></div></div></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${p.variants.length?p.variants.reduce((a,v)=>a+v.stock,0):p.stock}</td><td><span class="tag ${p.active?'':'warn'}">${p.active?'Active':'Hidden'}</span></td><td>${button('Edit','edit-product','outline sm',`data-id="${esc(p.id)}"`)}</td></tr>`).join('')}</tbody></table>${state.products.length?'':'<div class="empty">Your next best seller starts here. Add your first product.</div>'}</div></section>`;}
function appearance(){const s=state.settings;return `<form data-form="appearance"><section class="panel"><h2>Make it yours.</h2><p>Logo, colours, layout and hero content update your storefront. Upload your images in Media library, then choose them here.</p><div class="form-grid">${field('Store name','name',s.name)}${field('Tagline','tagline',s.tagline)}${field('Catalogue section title','catalogTitle',s.catalogTitle||'Explore the collection')}${field('Footer message','footerText',s.footerText||'')}${field('Shop navigation label','navShopLabel',s.navShopLabel||'Shop')}${field('About navigation label','navAboutLabel',s.navAboutLabel||'Our story')}${field('Accent colour','accent',s.accent,'color')}${field('Background colour','background',s.background,'color')}${field('Text colour','ink',s.ink,'color')}${select('Typography','font',s.font,[['serif','Editorial serif'],['sans','Modern sans serif']])}${select('Layout','layout',s.layout,[['editorial','Split editorial'],['minimal','Minimal catalogue']])}${imageSelect('logo',s.logo)}<div class="full">${field('Announcement bar','announcement',s.announcement)}${field('Hero headline','heroTitle',s.heroTitle)}${area('Hero description','heroText',s.heroText)}${field('Shop button label','heroButton',s.heroButton)}${imageSelect('heroImage',s.heroImage)}${check('Show hero section','showHero',s.showHero)}</div></div><div class="form-error"></div><button class="btn" type="submit">Save store design</button></section></form>`;}
function customPageFields(p={title:'',content:''}){return `<div class="custom-page">${field('Page title','pageTitle',p.title)}${area('Page content','pageContent',p.content)}${button('Remove page','remove-page','outline sm','type="button"')}<hr style="border:0;border-top:1px solid var(--line);margin:20px 0"></div>`;}
function contentPanel(){const s=state.settings;return `<form data-form="content"><section class="panel"><h2>Your story & contact details</h2><div class="form-grid">${field('Seller contact email','contactEmail',s.contactEmail,'email')}${field('Business phone','phone',s.phone)}<div class="full">${area('Business name and address','address',s.address)}${field('Instagram handle','instagram',s.instagram)}${field('About section heading','aboutTitle',s.aboutTitle)}${area('Your story','about',s.about)}${check('Show about section','showAbout',s.showAbout)}</div></div></section><section class="panel"><h2>Your store policies</h2><p>These policies belong to your business. Make them accurate for your products and operations before publishing. Platform policies apply separately.</p>${area('Delivery & shipping policy','shipping',s.shipping)}${area('Returns, refunds & cancellations','returns',s.returns)}${area('Customer privacy notice','privacy',s.privacy)}${area('Sales terms','terms',s.terms)}<h2>Additional store pages</h2><p>Add a size guide, care instructions, a service guide or another information page. Plain text keeps your store safe and readable.</p><div id="custom-pages">${(s.customPages||[]).map(customPageFields).join('')}</div>${button('+ Add page','add-page','outline sm','type="button"')}<div style="height:20px"></div><div class="form-error"></div><button class="btn" type="submit">Save content & policies</button></section></form>`;}
function paymentsPanel(){return `<div class="note">Connect your own approved merchant account. Credentials stay on the server and are never displayed back. Choose your default method in Store settings. Sandbox integrations cannot receive live store orders.</div><div class="payment-grid">${catalog.gateways.map(g=>{const c=state.gateways.find(x=>(x.provider||x.id)===g.id&&x.enabled);return `<article class="gateway-card"><div class="row"><h3>${esc(g.name)}</h3><span class="tag ${g.mode==='manual'?'warn':''}">${g.mode==='manual'?'Manual verification':'Automated adapter'}</span></div><p>${esc(g.note)}</p><span class="small">${g.currencies.join(' / ')} · ${c?'Configured · '+esc(c.environment):'Not configured'}</span><div class="row">${button(c?'Manage':'Set up','gateway','outline sm',`data-id="${g.id}"`)}${g.url?`<a href="${esc(g.url)}" target="_blank" rel="noopener">Provider details ↗</a>`:''}</div></article>`;}).join('')}</div>`;}
function mediaPanel(){return `<section class="panel"><h2>Your media library</h2><p>Upload product photos, your logo and banners. PNG, JPEG or WebP, up to 2 MB per file. Up to 200 files / 100 MB per store. Use images you have permission to publish.</p><label class="btn outline sm">+ Upload image<input class="hidden" type="file" data-upload accept="image/png,image/jpeg,image/webp"></label></section><div class="media-grid">${state.images.map(i=>`<article class="media-card"><img src="${esc(i.url||'/api/images/'+i.id)}" alt="${esc(i.name)}"><p>${esc(i.name)}</p>${button('Delete','delete-image','outline sm',`data-id="${esc(i.id)}"`)}</article>`).join('')}</div>${state.images.length?'':'<div class="empty">Your images will appear here. Then select them in your products or store designer.</div>'}`;}
function ordersPanel(){return `<section class="panel"><h2>Orders</h2><p>The latest 500 orders appear here; the store export includes full history. Payments must be verified before fulfilment. Manual payment methods require checking your provider or bank account.</p><div class="table-scroll"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>${state.orders.map(o=>`<tr><td>${esc(o.short_id||o.id.slice(0,10))}<p class="small">${new Date(o.created).toLocaleDateString()}</p></td><td>${esc(o.customer.name)}</td><td>${money(o.total,o.currency)}</td><td><span class="tag ${o.paid?'':'warn'}">${o.paid?'Paid':'Unverified'}</span></td><td>${esc(o.state)}</td><td>${button('View','order','outline sm',`data-id="${esc(o.id)}"`)}</td></tr>`).join('')}</tbody></table></div>${state.orders.length?'':'<div class="empty">New orders will appear here.</div>'}</section>`;}
function settingsPanel(){const s=state.settings;return `<form data-form="settings"><section class="panel"><h2>Delivery, tax & checkout</h2><div class="form-grid">${select('Store currency','currency',s.currency,[['JMD','JMD — Jamaican dollar'],['USD','USD — US dollar']])}${select('Default payment method','defaultPayment',s.defaultPayment,[['','Choose a method'],...state.gateways.filter(g=>g.enabled).map(g=>[g.provider||g.id,catalog.gateways.find(x=>x.id===(g.provider||g.id))?.name||g.name])])}${field('Flat delivery charge','shippingFee',s.shippingFee/100,'number')}${field('Free delivery from (0 disables)','freeShippingOver',s.freeShippingOver/100,'number')}${field('Tax percentage','taxPercent',s.taxBps/100,'number','Set only the tax you are required to collect. Prices exclude this configured tax.')}${field('Tax label','taxLabel',s.taxLabel)}${check('Offer store pickup','pickup',s.pickup)}${check('Offer delivery','shippingEnabled',s.shippingEnabled)}<div class="full">${field('Categories, separated with commas','categories',s.categories.join(', '))}</div></div><div class="form-error"></div><button class="btn" type="submit">Save settings</button></section></form><section class="panel"><h2>Your account & data</h2><p>${demo?'Sample data is stored only in this browser.':'Export your catalogue, settings, images and orders. Keep this file secure: it contains customer information.'}</p><div class="row" style="flex-wrap:wrap">${button('Export store data','export','outline sm')}${!demo?button('Change password','password','outline sm')+button('Cancel store rental','cancel-store','outline sm')+button('Request account deletion','delete-account','outline sm'):button('Reset demo','reset-demo','outline sm')}</div>${state.requests?.length?`<div class="note">Recent requests: ${state.requests.map(r=>esc(r.kind)).join(', ')}</div>`:''}</section>`;}
function dashboard(){const views={overview,products:productsPanel,appearance,content:contentPanel,media:mediaPanel,payments:paymentsPanel,orders:ordersPanel,settings:settingsPanel};shell((views[tab]||overview)());}
const cartKey=()=>`icss-cart-${demo?'demo':store.slug}`;
function cart(){return local.get(cartKey(),[]);}
function saveCart(lines){local.set(cartKey(),lines);}
function resolvedCart(){return cart().map(l=>{const p=store.products.find(p=>p.id===l.productId);if(!p)return null;const v=l.variantId?p.variants.find(v=>v.id===l.variantId):p;if(!v)return null;return {...l,product:p,name:p.name+(v!==p?' — '+v.name:''),price:v.price,stock:v.stock};}).filter(Boolean);}
function storeStyles(s){return `--accent:${esc(s.accent)};--bg:${esc(s.background)};--ink:${esc(s.ink)}`;}
function storeHTML(data,preview=false,policy=''){const s=data.settings;const list=data.products.filter(p=>p.active&&(category==='All'||p.category===category)&&p.name.toLowerCase().includes(search.toLowerCase()));list.sort((a,b)=>sort==='price-up'?a.price-b.price:sort==='price-down'?b.price-a.price:Number(b.featured)-Number(a.featured));
 const links=['shipping','returns','privacy','terms'];
 const card=p=>`<article class="product-card"><div class="picture" data-action="product-detail" data-id="${esc(p.id)}"><img src="${esc(p.image||'/assets/collection.svg')}" alt="${esc(p.name)}" loading="lazy">${p.featured?'<span class="badge">Selected favourite</span>':''}</div><h3>${esc(p.name)}</h3><p>${p.variants.length?'From ':''}${money(p.variants.length?Math.min(...p.variants.map(v=>v.price)):p.price,s.currency)}</p><button data-action="product-detail" data-id="${esc(p.id)}">${(p.variants.length?p.variants.some(v=>v.stock>0):p.stock>0)?'View product +':'Sold out'}</button></article>`;
 return `<div class="store ${esc(s.font)} ${esc(s.layout)}" style="${storeStyles(s)}">${s.announcement?`<div class="announcement">${esc(s.announcement)}</div>`:''}<nav class="store-nav"><a class="store-brand" href="${demo?'/demo?view=store':'/s/'+data.slug}">${s.logo?`<img src="${esc(s.logo)}" alt="${esc(s.name)}">`:esc(s.name)}</a><div class="row"><a class="shop-link" href="#collection">${esc(s.navShopLabel||'Shop')}</a>${s.showAbout?`<a class="shop-link" href="#our-story">${esc(s.navAboutLabel||'Our story')}</a>`:''}<button data-action="cart">Bag (${preview?0:cart().reduce((a,l)=>a+l.quantity,0)})</button></div></nav>${policy?`<article class="store-policy"><button class="back-link" data-action="store-home">← Back to the store</button><h1>${esc({shipping:'Delivery & shipping',returns:'Returns & refunds',privacy:'Privacy notice',terms:'Sales terms'}[policy])}</h1><p>${esc(s[policy])}</p></article>`:`${s.showHero?`<section class="store-hero"><div class="store-hero-copy"><small>${esc(s.tagline)}</small><h1>${esc(s.heroTitle)}</h1><p>${esc(s.heroText)}</p><a class="store-btn" href="#collection">${esc(s.heroButton)}</a></div>${s.heroImage?`<img src="${esc(s.heroImage)}" alt="${esc(s.name)} collection">`:''}</section>`:''}<section class="store-catalog" id="collection"><h2>${esc(s.catalogTitle||'Explore the collection')}</h2><div class="catalog-top"><div class="categories">${['All',...s.categories].map(c=>`<button data-category="${esc(c)}" class="${category===c?'active':''}">${esc(c)}</button>`).join('')}</div><div class="row"><input aria-label="Search products" data-search value="${esc(search)}" placeholder="Find something you’ll love"><select aria-label="Sort products" data-sort><option value="featured" ${sort==='featured'?'selected':''}>Featured</option><option value="price-up" ${sort==='price-up'?'selected':''}>Price: low to high</option><option value="price-down" ${sort==='price-down'?'selected':''}>Price: high to low</option></select></div></div><div class="product-grid">${list.map(card).join('')}</div>${list.length?'':'<p class="empty">No products match your search.</p>'}</section>${s.showAbout?`<section class="store-about" id="our-story"><h2>${esc(s.aboutTitle)}</h2><p>${esc(s.about)}</p></section>`:''}`}
 <footer class="store-footer"><div class="row"><div><h3>${esc(s.name)}</h3><p>${esc(s.footerText||s.tagline)}</p><p>${esc(s.address)}</p>${s.contactEmail?`<a href="mailto:${esc(s.contactEmail)}">${esc(s.contactEmail)}</a>`:''}${s.phone?`<p>${esc(s.phone)}</p>`:''}${s.instagram?`<p>Instagram: ${esc(s.instagram)}</p>`:''}</div><div>${(s.customPages||[]).map((p,i)=>`<p><button class="back-link" data-action="custom-page" data-index="${i}">${esc(p.title)}</button></p>`).join('')}${links.map(k=>`<p><button class="back-link" data-policy="${k}">${{shipping:'Delivery & shipping',returns:'Returns & refunds',privacy:'Privacy',terms:'Terms'}[k]}</button></p>`).join('')}</div><div><p>Secure payments through your selected provider.<br>Independent seller: ${esc(s.name)}</p><p>Store hosted on <a href="/">ICSS Plaza</a><br>Platform operated by iCreate Solutions & Services.</p><a href="mailto:icreatesolutions.ja@gmail.com">Report this store</a></div></div></footer></div>`;
}
function renderStore(policy=''){const banner=demo?`<div class="banner"><span>Demo storefront · No real payments. Use sample information only.</span><a class="btn sm" href="/demo">← Edit this demo</a></div>`:'';app.innerHTML=banner+storeHTML(store,false,policy);document.title=store.settings.name+' | ICSS Plaza';}
function previewStore(){store={...state};search='';category='All';sort='featured';showModal('<h2>Store preview</h2><p>Use View storefront for the full-size experience. Save changes before previewing.</p><div class="preview-holder">'+storeHTML(store,true)+'</div>');}
function productDialog(pid){const p=store.products.find(p=>p.id===pid&&p.active);if(!p)return;showModal(`<div class="split"><img src="${esc(p.image||'/assets/collection.svg')}" alt="${esc(p.name)}" style="border-radius:9px"><div><span class="tag">${esc(p.category)}</span><h2 style="margin-top:15px">${esc(p.name)}</h2><p class="preline">${esc(p.description)}</p><form data-form="add-cart" data-id="${esc(p.id)}">${p.variants.length?select('Choose an option','variantId','',p.variants.map(v=>[v.id,`${v.name} — ${money(v.price,store.settings.currency)} (${v.stock} available)`])):`<p>${money(p.price,store.settings.currency)} · ${p.stock} available</p>`}${field('Quantity','quantity',1,'number')}<div class="form-error"></div><button class="store-btn" type="submit">Add to bag +</button></form></div></div>`);}
function cartDialog(){const lines=resolvedCart();showModal(`<h2>Your bag</h2>${lines.map((l,i)=>`<div class="cart-line"><img src="${esc(l.product.image||'/assets/collection.svg')}" alt=""><div class="details"><strong>${esc(l.name)}</strong><p style="margin:5px 0">${money(l.price,store.settings.currency)}</p></div><input aria-label="Quantity for ${esc(l.name)}" type="number" min="1" max="99" value="${l.quantity}" data-cart-quantity="${i}"><button data-action="remove-cart" data-index="${i}" aria-label="Remove ${esc(l.name)}">×</button></div>`).join('')}${lines.length?`<div class="order-total"><strong>Subtotal</strong><strong>${money(lines.reduce((a,l)=>a+l.price*l.quantity,0),store.settings.currency)}</strong></div><p>Delivery and configured taxes are calculated at checkout.</p>${button('Continue to checkout →','checkout')}`:'<p>Your bag is waiting for something good.</p>'}`);}
function checkoutDialog(){const s=store.settings,lines=resolvedCart();if(!lines.length)return cartDialog();const subtotal=lines.reduce((a,l)=>a+l.price*l.quantity,0);const tax=Math.round(subtotal*s.taxBps/10000);const shipping=s.freeShippingOver&&subtotal>=s.freeShippingOver?0:s.shippingFee;
 const gs=demo?state.gateways.filter(g=>g.enabled).map(g=>({...g,id:g.provider||g.id,name:catalog.gateways.find(x=>x.id===(g.provider||g.id))?.name||g.name})):store.gateways;
 showModal(`<h2>${demo?'Try a sample checkout':'Checkout'}</h2>${demo?'<div class="note">Use fictional details. No payment will be taken and no real order will be sent.</div>':''}<form data-form="checkout">${field('Full name','name',demo?'Demo Customer':'')}${field('Email','email',demo?'sample@example.com':'','email')}${field('Phone','phone',demo?'0000000000':'')}${select('Delivery method','delivery',s.shippingEnabled?'shipping':'pickup',[[...(s.shippingEnabled?['shipping','Delivery']:[])],[...(s.pickup?['pickup','Pickup']:[])]].filter(x=>x.length))}${area('Delivery address (required for delivery)','address',demo?'Demo address, Jamaica':'')}${select('Payment method','gateway',s.defaultPayment,gs.map(g=>[g.id,g.name+(g.mode==='manual'?' — manual verification':'')]))}<div class="order-total"><span>Subtotal</span><strong>${money(subtotal,s.currency)}</strong></div><div class="order-total"><span>${esc(s.taxLabel)} (${s.taxBps/100}%)</span><strong>${money(tax,s.currency)}</strong></div><div class="order-total"><span>Delivery</span><strong id="shipping-total">${money(s.shippingEnabled?shipping:0,s.currency)}</strong></div><div class="order-total"><strong>Total</strong><strong id="checkout-total" data-subtotal="${subtotal+tax}" data-shipping="${shipping}">${money(subtotal+tax+(s.shippingEnabled?shipping:0),s.currency)}</strong></div><p>Seller: ${esc(s.name)}. ${demo?'Sample transaction.':'You will pay through the selected merchant payment method.'}</p><label class="field check"><input type="checkbox" name="acceptTerms" required><span>I accept this seller’s <button class="back-link" type="button" data-action="checkout-policy" data-id="terms">sales terms</button>, <button class="back-link" type="button" data-action="checkout-policy" data-id="shipping">delivery</button> and <button class="back-link" type="button" data-action="checkout-policy" data-id="returns">returns policy</button> and have read the <button class="back-link" type="button" data-action="checkout-policy" data-id="privacy">privacy notice</button>.</span></label><div class="form-error"></div><button class="btn" type="submit">${demo?'Place sample order':'Place order & continue'} →</button></form>`);
}
function variantRow(v={id:uid(),name:'',price:0,stock:0}){return `<div class="variant-row" data-variant-id="${esc(v.id)}"><input aria-label="Variant name" data-v-name placeholder="Size / colour" value="${esc(v.name)}"><input aria-label="Variant price" data-v-price type="number" step="0.01" min="0" value="${v.price/100}"><input aria-label="Variant stock" data-v-stock type="number" min="0" value="${v.stock}"><button type="button" data-action="remove-variant" aria-label="Remove variant">×</button></div>`;}
function editProduct(pid){const p=state.products.find(x=>x.id===pid)||{id:'',name:'',description:'',category:state.settings.categories[0]||'General',price:0,stock:0,sku:'',image:'',active:true,featured:false,type:'physical',variants:[]};showModal(`<h2>${p.id?'Edit product':'Add a product'}</h2><form data-form="product" data-id="${esc(p.id)}"><div class="form-grid">${field('Product name','name',p.name)}${field('SKU','sku',p.sku)}<div class="full">${area('Description','description',p.description)}</div>${field('Category','category',p.category)}${select('Product type','type',p.type,[['physical','Physical product'],['service','Service (manual fulfilment)']])}${field('Base price ('+state.settings.currency+')','price',p.price/100,'number')}${field('Stock / available quantity','stock',p.stock,'number')}<div class="full">${imageSelect('image',p.image)}${check('Visible in store','active',p.active)}${check('Featured product','featured',p.featured)}<label class="field">Options / variants<span class="helper">Optional. Each option has its own price and stock. Base price and stock apply only when there are no variants.</span></label><div class="variants">${p.variants.map(variantRow).join('')}</div>${button('+ Add option','add-variant','outline sm','type="button"')}<div style="height:20px"></div></div></div><div class="form-error"></div><div class="row"><button class="btn" type="submit">Save product</button>${p.id?button('Delete product','delete-product','outline sm',`type="button" data-id="${esc(p.id)}"`):''}</div></form>`);}
function gatewayDialog(provider){const g=catalog.gateways.find(g=>g.id===provider),configured=state.gateways.find(c=>(c.provider||c.id)===provider&&c.enabled);const labels={buttonURL:'Fygaro payment button HTTPS URL',keyId:'Fygaro API key ID',secret:provider==='wipay'?'WiPay verification API key':'API secret',clientId:'PayPal client ID',accountNumber:'WiPay account number',paymentURL:'Approved merchant hosted payment URL (optional)',instructions:'Customer payment instructions',label:'Payment method display name'};showModal(`<h2>${esc(g.name)}</h2><p>${esc(g.note)}</p>${demo?'<div class="note">Demo mode: do not enter real payment credentials. Configuration is simulated.</div>':''}<form data-form="gateway" data-id="${g.id}">${g.mode==='automated'?select('Environment','environment',configured?.environment||'sandbox',[['sandbox','Sandbox / testing'],['live','Live (approved account required)']]):''}${g.fields.map(f=>f==='instructions'?area(labels[f],f,''):field(labels[f],f,'',f==='secret'?'password':'text',configured?'Leave blank to keep your current value.':'')).join('')}${provider==='fygaro'&&!demo?`<div class="note">Configure your payment button Hook URL as:<br><strong>${esc(location.origin+'/api/payments/'+state.id+'/fygaro/hook')}</strong><br>Use matching API key credentials for signing hooks. A return URL alone does not verify a payment.</div>`:''}<div class="form-error"></div><div class="row"><button class="btn" type="submit">${demo?'Simulate setup':'Save & enable'}</button>${configured?button('Disable','disable-gateway','outline sm',`type="button" data-id="${g.id}"`):''}</div></form>`);}
function orderDialog(oid){const o=state.orders.find(o=>o.id===oid);if(!o)return;const manual=catalog.gateways.find(g=>g.id===o.gateway)?.mode==='manual';showModal(`<h2>Order ${esc(o.short_id||o.id.slice(0,10))}</h2><div class="status-line"><span class="tag ${o.paid?'':'warn'}">${o.paid?'Paid':'Payment unverified'}</span><span class="tag">${esc(o.state)}</span><span class="small">${esc(o.gateway)}</span></div><p><strong>${esc(o.customer.name)}</strong><br>${esc(o.customer.email)}<br>${esc(o.customer.phone)}<br>${esc(o.customer.address)}</p><p>Delivery: ${esc(o.delivery||'shipping')}</p>${o.lines.map(l=>`<div class="order-total"><span>${esc(l.name)} × ${l.quantity}</span><strong>${money(l.price*l.quantity,o.currency)}</strong></div>`).join('')}<div class="order-total"><strong>Total</strong><strong>${money(o.total,o.currency)}</strong></div>${o.transaction_id?`<p>Payment reference: ${esc(o.transaction_id)}</p>`:''}<form data-form="order" data-id="${esc(o.id)}">${select('Order status','state',o.state,['new','processing','fulfilled','cancelled'].map(k=>[k,k]))}${!o.paid&&manual?check('I verified this payment in my provider / bank account','markPaid',false)+field('Verified transaction reference','reference'):''}<div class="form-error"></div><button class="btn" type="submit">Update order</button></form><p style="margin-top:20px">Refunds must be issued in your provider account and reconciled with support. Cancellation releases reserved stock only for unpaid orders.</p>`);}
async function operatorPage(){if(!session.operator){location.href='/login';return;}const d=await api('/api/operator');app.innerHTML=nav()+`<main class="wrap"><section class="section"><div class="section-head"><div><div class="eyebrow">Platform operator</div><h1 style="font-size:2.7rem">The plaza, at a glance.</h1></div>${button('Sign out','logout','outline sm')}</div><div class="panel"><h2>Store rentals</h2><p>Activate paid rentals only after agreeing pricing and billing with the merchant. The platform does not automatically collect rental charges.</p><div class="table-scroll"><table><thead><tr><th>Store</th><th>Owner</th><th>Rental status</th><th>Trial ends</th><th>Action</th></tr></thead><tbody>${d.tenants.map(t=>`<tr><td>${esc(t.settings.name)}<p>/s/${esc(t.slug)}</p></td><td>${esc(t.email)}</td><td>${esc(t.status)}</td><td>${new Date(t.trial_end).toLocaleDateString()}</td><td><button class="btn outline sm" data-action="rental" data-id="${t.id}">Manage</button> <button class="btn outline sm" data-action="issue-reset" data-id="${t.id}">Reset access</button></td></tr>`).join('')}</tbody></table></div></div><div class="panel"><h2>Service requests</h2>${d.requests.map(r=>`<p><strong>${esc(r.slug)} · ${esc(r.kind)}</strong><br>${esc(r.note)}<br>${new Date(r.created).toLocaleString()}</p>`).join('')||'<p>No requests yet.</p>'}</div><div class="panel"><h2>Recent audit events</h2><div class="table-scroll"><table><thead><tr><th>Time</th><th>Store ID</th><th>Action</th></tr></thead><tbody>${d.audit.map(a=>`<tr><td>${new Date(a.created).toLocaleString()}</td><td>${esc(a.tenant_id)}</td><td>${esc(a.action)}</td></tr>`).join('')}</tbody></table></div></div></section></main>`+footer();}
async function saveSettings(payload){if(demo){state.settings={...state.settings,...payload};saveDemo();}else{const r=await api('/api/admin/'+state.id+'/settings','PUT',payload);state.settings=r.settings;}toast('Saved. Your store has been updated.');dashboard();}
async function adminMutation(action,method,data){if(!demo)await api('/api/admin/'+state.id+'/'+action,method,data);await refresh();}
function formData(form){const d=Object.fromEntries(new FormData(form));for(const box of form.querySelectorAll('input[type=checkbox]'))d[box.name]=box.checked;return d;}
function download(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
document.addEventListener('submit',async e=>{
 const form=e.target;if(!form.matches('[data-form]'))return;e.preventDefault();const kind=form.dataset.form,data=formData(form),submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
 try{
 if(['login','signup','reset'].includes(kind)){await api('/api/'+kind,'POST',data);if(kind==='reset'){toast('Password updated. Please sign in.');location.href='/login';}else location.href='/admin';return;}
 if(['appearance','content'].includes(kind)){if(kind==='content'){data.customPages=[...form.querySelectorAll('.custom-page')].map(p=>({title:p.querySelector('[name=pageTitle]').value,content:p.querySelector('[name=pageContent]').value}));delete data.pageTitle;delete data.pageContent;}await saveSettings(data);return;}
 if(kind==='settings'){for(const k of ['shippingFee','freeShippingOver'])data[k]=Math.round(Number(data[k])*100);data.taxBps=Math.round(Number(data.taxPercent)*100);delete data.taxPercent;data.categories=data.categories.split(',').map(x=>x.trim()).filter(Boolean);await saveSettings(data);return;}
 if(kind==='product'){
 data.price=Math.round(Number(data.price)*100);data.stock=Number(data.stock);data.variants=[...form.querySelectorAll('[data-variant-id]')].map(r=>({id:r.dataset.variantId,name:r.querySelector('[data-v-name]').value,price:Math.round(Number(r.querySelector('[data-v-price]').value)*100),stock:Number(r.querySelector('[data-v-stock]').value)}));const pid=form.dataset.id;
 if(!data.name||!Number.isSafeInteger(data.price)||data.price<0||!Number.isSafeInteger(data.stock)||data.stock<0||data.variants.some(v=>!v.name||!Number.isSafeInteger(v.price)||v.price<0||!Number.isSafeInteger(v.stock)||v.stock<0))throw Error('Add a name, valid price and whole-number stock for every option.');
 if(demo){if(pid)state.products=state.products.map(p=>p.id===pid?{...data,id:pid}:p);else state.products.unshift({...data,id:uid()});saveDemo();}else{await adminMutation('products'+(pid?'/'+pid:''),pid?'PUT':'POST',data);}modal.close();toast('Product saved.');dashboard();return;
 }
 if(kind==='gateway'){
 const provider=form.dataset.id;if(demo){state.gateways=state.gateways.filter(g=>(g.provider||g.id)!==provider);state.gateways.push({provider,enabled:true,environment:data.environment||'live',configured:true});saveDemo();}else await adminMutation('gateways/'+provider,'PUT',{...data,enabled:true});modal.close();toast(demo?'Demo method configured. No real credentials were saved.':'Payment method saved.');dashboard();return;
 }
 if(kind==='order'){
 const oid=form.dataset.id;if(demo){const o=state.orders.find(o=>o.id===oid);if(data.state==='fulfilled'&&!o.paid&&!data.markPaid)throw Error('Confirm payment before fulfilment.');if(data.markPaid){if(!data.reference)throw Error('Add a sample transaction reference.');o.paid=true;o.transaction_id='demo:'+data.reference;}if(o.state==='cancelled'&&data.state!=='cancelled')throw Error('Cancelled orders cannot be reopened.');if(data.state==='cancelled'&&o.paid)throw Error('Paid orders need refund reconciliation first.');if(data.state==='cancelled'&&o.state!=='cancelled'){for(const l of o.lines){const p=state.products.find(p=>p.id===l.productId);const target=l.variantId?p?.variants.find(v=>v.id===l.variantId):p;if(target)target.stock+=l.quantity;}}o.state=data.state;saveDemo();}else await adminMutation('orders/'+oid,'PATCH',data);modal.close();toast('Order updated.');dashboard();return;
 }
 if(kind==='add-cart'){
 const p=store.products.find(p=>p.id===form.dataset.id),v=p.variants.length?p.variants.find(v=>v.id===data.variantId):p,qty=Number(data.quantity);if(!v||!Number.isInteger(qty)||qty<1||qty>99)throw Error('Choose a valid quantity and option.');const c=cart(),l=c.find(l=>l.productId===p.id&&l.variantId===(data.variantId||''));if(qty+(l?.quantity||0)>v.stock)throw Error('There is not enough stock for that quantity.');if(l)l.quantity+=qty;else c.push({productId:p.id,variantId:data.variantId||'',quantity:qty});saveCart(c);modal.close();if(location.pathname.startsWith('/s/')||location.search.includes('view=store'))renderStore();toast('Added to your bag.');return;
 }
 if(kind==='checkout'){
 if(!data.acceptTerms)throw Error('Please accept the seller policies.');if(!data.name||!data.email||!data.phone||(data.delivery==='shipping'&&!data.address))throw Error('Complete your contact and delivery details.');
 const lines=resolvedCart();let result;
 if(demo){const subtotal=lines.reduce((a,l)=>a+l.price*l.quantity,0),s=store.settings;const shipping=data.delivery==='pickup'||(s.freeShippingOver&&subtotal>=s.freeShippingOver)?0:s.shippingFee,tax=Math.round(subtotal*s.taxBps/10000);for(const l of lines){const p=state.products.find(p=>p.id===l.productId),v=l.variantId?p.variants.find(v=>v.id===l.variantId):p;if(l.quantity>v.stock)throw Error('A sample product has insufficient stock.');}for(const l of lines){const p=state.products.find(p=>p.id===l.productId),v=l.variantId?p.variants.find(v=>v.id===l.variantId):p;v.stock-=l.quantity;}const o={id:uid(),short_id:'DEMO-'+uid().slice(0,6),total:subtotal+tax+shipping,subtotal,tax,shipping,currency:s.currency,customer:{name:data.name,email:data.email,phone:data.phone,address:data.address},lines:lines.map(({product,...l})=>l),gateway:data.gateway,delivery:data.delivery,state:'new',paid:false,created:Date.now()};state.orders.unshift(o);saveDemo();result={order:o};store=state;
 }else{
 const request={customer:{name:data.name,email:data.email,phone:data.phone,address:data.address},lines:cart(),gateway:data.gateway,delivery:data.delivery,acceptTerms:true};
 const requestKey=JSON.stringify(request),old=local.get('icss-checkout-'+store.slug,null);const pending=old?.requestKey===requestKey?old:{requestKey,idempotency:uid(),orderToken:uid()+uid()};local.set('icss-checkout-'+store.slug,pending);
 result=await api('/api/stores/'+store.slug+'/orders','POST',{...request,idempotency:pending.idempotency,orderToken:pending.orderToken});local.set('icss-order-'+store.slug,{id:result.order.id,token:result.token});local.remove('icss-checkout-'+store.slug);
 }
 saveCart([]);modal.close();renderStore();showOrderReceipt(result.order);return;
 }
 if(kind==='rental'){await api('/api/operator/'+form.dataset.id,'PATCH',data);modal.close();await operatorPage();toast('Rental status updated.');return;}
 if(kind==='password'){if(data.password!==data.confirm)throw Error('New passwords do not match.');await api('/api/password','POST',data);session=await api('/api/session');modal.close();toast('Password changed. Other sessions were signed out.');return;}
 if(kind==='request'){
 if(!data.confirm)throw Error('Please confirm your request.');await adminMutation('requests','POST',{kind:form.dataset.kind,note:data.note});modal.close();toast('Your request was recorded.');dashboard();return;
 }
 }catch(error){const box=form.querySelector('.form-error');if(box){box.className='form-error error';box.textContent=error.message;}else toast(error.message);}finally{if(submit)submit.disabled=false;}
});
function showOrderReceipt(o){showModal(`<h2>${demo?'Sample order placed':'Order received'}</h2><p>Reference: <strong>${esc(o.short_id||o.id)}</strong></p><div class="note ${o.paid?'':'warn'}">${o.paid?'Payment confirmed.':demo?'Demo order saved. View it under Orders in the demo dashboard. No payment was taken.':'Your order is recorded. Payment is pending verification. Keep this order reference.'}</div><p>Total: ${money(o.total,o.currency)}</p>${o.payment?.instructions?`<p class="preline">${esc(o.payment.instructions)}</p>`:''}${o.payment?.url?`<a class="btn" href="${esc(o.payment.url)}" rel="noreferrer">Continue to payment provider ↗</a>`:''}${o.paymentError?`<p>${esc(o.paymentError)}</p>`:''}${!demo?(!o.paid&&!o.payment?.url&&o.state!=='cancelled'?button('Retry payment setup','retry-payment','outline sm'):'')+button('Refresh payment status','order-status','outline sm'):`<a class="btn outline" href="/demo?tab=orders">View demo orders →</a>`}`);}
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action],[data-tab],[data-category],[data-policy]');if(!el)return;
 try{
 if(el.dataset.tab){tab=el.dataset.tab;dashboard();return;}
 if(el.dataset.category){category=el.dataset.category;renderStore();return;}
 if(el.dataset.policy){renderStore(el.dataset.policy);window.scrollTo(0,0);return;}
 const action=el.dataset.action,pid=el.dataset.id;
 if(action==='close'){modal.close();return;}
 if(action==='logout'){await api('/api/logout','POST',{});location.href='/';return;}
 if(action==='reset-demo'){showModal('<h2>Reset your demo?</h2><p>This clears your sample products, settings, orders and uploaded images in this browser.</p>'+button('Reset demo','confirm-reset'));return;}
 if(action==='confirm-reset'){local.remove(demoKey);local.remove('icss-cart-demo');loadDemo();saveDemo();modal.close();dashboard();toast('Demo reset.');return;}
 if(action==='preview'){previewStore();return;}
 if(action==='add-product'||action==='edit-product'){editProduct(pid);return;}
 if(action==='add-page'){const list=modal.open?modal.querySelector('#custom-pages'):document.querySelector('#custom-pages');if(list.children.length>=10)throw Error('Add up to 10 pages.');list.insertAdjacentHTML('beforeend',customPageFields());return;}
 if(action==='remove-page'){el.closest('.custom-page').remove();return;}
 if(action==='custom-page'){const p=store.settings.customPages?.[Number(el.dataset.index)];if(p)showModal(`<h2>${esc(p.title)}</h2><p class="preline">${esc(p.content)}</p>`);return;}
 if(action==='add-variant'){modal.querySelector('.variants').insertAdjacentHTML('beforeend',variantRow());return;}
 if(action==='remove-variant'){el.closest('.variant-row').remove();return;}
 if(action==='delete-product'){showModal(`<h2>Delete this product?</h2><p>It will be removed from your catalogue. Existing order records keep their item details.</p>${button('Delete product','confirm-delete-product','danger',`data-id="${esc(pid)}"`)}`);return;}
 if(action==='confirm-delete-product'){if(demo){state.products=state.products.filter(p=>p.id!==pid);saveDemo();}else await adminMutation('products/'+pid,'DELETE');modal.close();dashboard();toast('Product deleted.');return;}
 if(action==='gateway'){gatewayDialog(pid);return;}
 if(action==='disable-gateway'){if(state.settings.defaultPayment===pid&&state.settings.published)throw Error('Choose another default method in Store settings first.');if(demo){state.gateways=state.gateways.map(g=>(g.provider||g.id)===pid?{...g,enabled:false}:g);saveDemo();}else await adminMutation('gateways/'+pid,'PUT',{enabled:false});modal.close();dashboard();toast('Payment method disabled.');return;}
 if(action==='delete-image'){
 const image=state.images.find(i=>i.id===pid),url=image?.url||'/api/images/'+pid;if(JSON.stringify(state.settings).includes(url)||state.products.some(p=>p.image===url))throw Error('Replace this image where it is used before deleting.');
 if(demo){state.images=state.images.filter(i=>i.id!==pid);saveDemo();}else await adminMutation('images/'+pid,'DELETE');dashboard();toast('Image deleted.');return;
 }
 if(action==='publish'||action==='unpublish'){await saveSettings({published:action==='publish'});return;}
 if(action==='export'){if(demo)download(state,'icss-plaza-demo-export.json');else{const d=await api('/api/admin/'+state.id+'/export');download(d,state.slug+'-export.json');}return;}
 if(action==='password'){showModal(`<h2>Change your password</h2><form data-form="password">${field('Current password','currentPassword','','password')}${field('New password (at least 12 characters)','password','','password')}${field('Confirm new password','confirm','','password')}<div class="form-error"></div><button class="btn" type="submit">Change password</button></form>`);return;}
 if(action==='cancel-store'||action==='delete-account'){const cancel=action==='cancel-store';showModal(`<h2>${cancel?'Cancel your rental?':'Request account deletion?'}</h2><p>${cancel?'This immediately takes your store offline. Export your records first. Customer orders, refunds and outstanding rental billing must be resolved separately.':'This records a deletion request for the operator to review. It does not immediately erase records that may be subject to legal retention requirements.'}</p><form data-form="request" data-kind="${cancel?'cancellation':'deletion'}">${area('Notes for support','note')}${check('I understand and confirm this request','confirm',false)}<div class="form-error"></div><button class="btn danger" type="submit">${cancel?'Cancel and take store offline':'Record deletion request'}</button></form>`);return;}
 if(action==='order'){orderDialog(pid);return;}
 if(action==='product-detail'){if(modal.open)modal.close();productDialog(pid);return;}
 if(action==='cart'){if(modal.open)modal.close();cartDialog();return;}
 if(action==='remove-cart'){const c=cart();c.splice(Number(el.dataset.index),1);saveCart(c);modal.close();cartDialog();return;}
 if(action==='checkout'){modal.close();checkoutDialog();return;}
 if(action==='checkout-policy'){const titles={terms:'Sales terms',shipping:'Delivery policy',returns:'Returns policy',privacy:'Privacy notice'};const form=modal.querySelector('form');let box=modal.querySelector('.checkout-policy-view');if(!box){box=document.createElement('section');box.className='checkout-policy-view note preline';form.prepend(box);}box.innerHTML=`<strong>${titles[pid]}</strong><br>${esc(store.settings[pid])}`;box.scrollIntoView({block:'nearest'});return;}
 if(action==='store-home'){renderStore();return;}
 if(action==='retry-payment'){const saved=local.get('icss-order-'+store.slug,null);if(!saved)throw Error('No saved order reference.');const r=await api('/api/orders/'+saved.id+'/payment','POST',{token:saved.token});modal.close();showOrderReceipt(r.order);return;}
 if(action==='order-status'){const saved=local.get('icss-order-'+store.slug,null);if(!saved)throw Error('No saved order reference in this browser.');const r=await api('/api/orders/'+saved.id+'?token='+saved.token);modal.close();showOrderReceipt(r.order);return;}
 if(action==='rental'){showModal(`<h2>Manage store rental</h2><p>Paid activation is a manual operator action after a written rental agreement.</p><form data-form="rental" data-id="${esc(pid)}">${select('Rental status','status','active',['active','trial','suspended','cancelled'].map(x=>[x,x]))}<div class="form-error"></div><button class="btn" type="submit">Update rental status</button></form>`);return;}
 if(action==='issue-reset'){const r=await api('/api/operator/'+pid+'/reset','POST',{});showModal(`<h2>One-time access reset</h2><p>Verify the merchant’s identity before providing this token. It expires in 60 minutes. Direct them to /reset.</p><label class="field">Reset token<input readonly value="${esc(r.token)}"></label>`);return;}
 }catch(error){toast(error.message);}
});
document.addEventListener('input',e=>{
 if(e.target.closest('#mini-editor')){const d=formData(e.target.closest('form')),s=demoStore().settings;document.querySelector('#mini-preview').innerHTML=mini({...s,...d});}
 if(e.target.matches('[data-search]')){const pos=e.target.selectionStart;search=e.target.value;renderStore();const input=document.querySelector('[data-search]');input?.focus();input?.setSelectionRange(pos,pos);}
});
document.addEventListener('change',async e=>{
 try{
 if(e.target.matches('[data-sort]')){sort=e.target.value;renderStore();}
 if(e.target.matches('[data-cart-quantity]')){const c=cart(),index=Number(e.target.dataset.cartQuantity),qty=Number(e.target.value),line=resolvedCart()[index];if(!Number.isInteger(qty)||qty<1||qty>99||qty>line.stock)throw Error('Choose a whole quantity within available stock.');c[index].quantity=qty;saveCart(c);modal.close();cartDialog();}
 if(e.target.name==='delivery'&&e.target.closest('[data-form=checkout]')){const total=modal.querySelector('#checkout-total');const shipping=e.target.value==='pickup'?0:Number(total.dataset.shipping);modal.querySelector('#shipping-total').textContent=money(shipping,store.settings.currency);total.textContent=money(Number(total.dataset.subtotal)+shipping,store.settings.currency);}
 if(e.target.matches('[data-upload]')){
 const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('Choose a PNG, JPEG or WebP image up to 2 MB.');
 const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});
 if(demo){if(state.images.length>=10)throw Error('Demo is limited to 10 images. Reset it to start again.');const i={id:uid(),name:file.name,url:data};const next={...state,images:[...state.images,i]};try{localStorage.setItem(demoKey,JSON.stringify(next));}catch{throw Error('Demo browser storage is full. Try a smaller image.');}state=next;}else await adminMutation('images','POST',{name:file.name,data});toast('Image uploaded. Choose it in your store designer or products.');dashboard();
 }
 }catch(error){toast(error.message);}
});
async function boot(){
 catalog=await api('/api/catalog');const path=location.pathname.replace(/\/$/,'')||'/';
 if(path==='/'){landing();return;}
 if(path.startsWith('/legal')){legal();return;}
 if(['/login','/signup','/reset'].includes(path)){session=await api('/api/session');authPage(path.slice(1));return;}
 if(path==='/demo'){
 demo=true;loadDemo();const params=new URLSearchParams(location.search);tab=params.get('tab')||'overview';if(params.get('view')==='store'){store=state;renderStore();}else dashboard();return;
 }
 if(path.startsWith('/s/')){
 const slug=path.split('/')[2];const d=await api('/api/stores/'+slug);store=d;renderStore();const saved=local.get('icss-order-'+slug,null);if(saved&&new URLSearchParams(location.search).has('payment')){try{const r=await api('/api/orders/'+saved.id+'?token='+saved.token);showOrderReceipt(r.order);}catch(error){toast(error.message);}}return;
 }
 session=await api('/api/session');if(!session.user){location.href='/login';return;}
 if(path==='/operator'){await operatorPage();return;}
 if(path==='/admin'){
 if(!session.tenants.length){if(session.operator){location.href='/operator';return;}throw Error('No store is connected to this account. Contact support.');}
 state=session.tenants[0];await refresh();dashboard();return;
 }
 throw Error('Page not found.');
}
boot().catch(errorPage);
